export type OrderStatus = 'new' | 'processing' | 'shipped' | 'delivered' | 'cancelled';

export interface Order {
  id: string;
  number: string;
  customer: string;
  email: string;
  status: OrderStatus;
  items: number;
  total: number;
  payment: 'card' | 'cash' | 'invoice';
